// Gameplay CTAs go straight to /play; links that mean the homepage stay on /.
// Covers the shared nav/footer, the build-time no-JS nav and every article and
// blog-index page as generated by the blog transform.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { parse } from 'node-html-parser';
import * as B from '../scripts/blog/transform.mjs';

const HOME = /^(\/|\/index(\.html)?|https?:\/\/(www\.)?supplychaindisaster\.com\/?)([?#].*)?$/i;
// A link to the homepage reads as "go play" when it's an arrow CTA or uses gameplay wording
const GAMEPLAY = /→\s*$|^(play|start|try|begin|run your|pick your|choose your|explore the simulation)\b/i;
const label = (a) => a.text.replace(/\s+/g, ' ').trim();
const homeboundCtas = (root) => root.querySelectorAll('a')
    .filter(a => HOME.test((a.getAttribute('href') || '').trim()) && GAMEPLAY.test(label(a)))
    .map(a => label(a));

const catalog = B.buildCatalog('.');

test('generated articles: no gameplay CTA points at the homepage; breadcrumb Home still does', () => {
    const failures = [];
    for (const post of catalog.posts) {
        const { html } = B.transformArticle(readFileSync(post.file, 'utf8'), post.file, catalog);
        const root = parse(html);
        const bad = homeboundCtas(root);
        if (bad.length) failures.push(`${post.file}: ${bad.join(' | ')}`);
        const home = root.querySelector('.ab-crumbs a');
        if (home?.getAttribute('href') !== '/' || label(home) !== 'Home') failures.push(`${post.file}: breadcrumb Home`);
        const play = root.querySelector('.ab-module-btn');
        if (play && !play.getAttribute('href').startsWith('/play')) failures.push(`${post.file}: module button ${play.getAttribute('href')}`);
    }
    assert.deepEqual(failures, []);
});

test('generated blog index pages: no gameplay CTA points at the homepage', () => {
    const src = readFileSync('blog.html', 'utf8');
    for (let page = 1; page <= B.pageCount(catalog); page++) {
        const root = parse(B.transformIndex(src, catalog, page));
        assert.deepEqual(homeboundCtas(root), [], `blog page ${page}`);
        assert.ok(root.querySelector('.ab-module-btn')?.getAttribute('href').startsWith('/play'), `blog page ${page} module button`);
    }
});

test('shared components: Play goes to /play; logos stay on /', () => {
    // Template-literal sources (not parseable as HTML), so match the anchors as written
    const nav = readFileSync('src/shared/nav.js', 'utf8');
    assert.match(nav, /<a href="\/play" class="nav-link nav-link--cta/);
    assert.match(nav, /<a href="\/" class="nav-logo"/);

    const footer = readFileSync('src/shared/footer.js', 'utf8');
    assert.match(footer, /<a href="\/play" class="footer-link">Play Game<\/a>/);
    assert.match(footer, /<a href="\/" class="footer-logo-link"/);
});

test('build-time no-JS nav: Play Free goes to /play and Home stays on /', () => {
    const block = readFileSync('vite.config.js', 'utf8').match(/STATIC_SEO_NAV = `([\s\S]*?)`/)[1];
    const links = parse(block.replace(/<\/?noscript[^>]*>/g, '')).querySelectorAll('a');
    assert.equal(links.find(a => label(a) === 'Play Free').getAttribute('href'), '/play');
    assert.equal(links.find(a => label(a) === 'Home').getAttribute('href'), '/');
});
